draw:
var eps0 = 8.854e-12;
var kap = p.kappa, V = p.volts, xcm = p.x;
var Lcm = 10.0, wcm = 8.0, dmm = 0.50;
var Lm = Lcm / 100, wm = wcm / 100, dm = dmm / 1000;
var xm = xcm / 100;
var Cx = eps0 * wm * (Lm - xm + kap * xm) / dm;   // farads
var F = eps0 * wm * (kap - 1) * V * V / (2 * dm); // newtons, constant in x

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";
ctx.lineWidth = 1.5;

var px0 = W * 0.10, plateL = W * 0.62;
var yTop = H * 0.20, yBot = H * 0.40;

// plates
ctx.fillStyle = C.figure;
ctx.fillRect(px0, yTop - 7, plateL, 7);
ctx.fillRect(px0, yBot, plateL, 7);

// slab, inserted a fraction x/L from the left
var frac = xm / Lm;
var slabW = plateL * frac;
ctx.globalAlpha = 0.35; ctx.fillStyle = C.faint;
ctx.fillRect(px0, yTop, slabW, yBot - yTop);
ctx.globalAlpha = 1;
ctx.strokeStyle = C.rule;
ctx.strokeRect(px0 - plateL * 0.34, yTop, plateL * 0.34 + slabW, yBot - yTop);
ctx.fillStyle = C.ink;
ctx.fillText("slab, kappa = " + kap.toFixed(1), px0 - plateL * 0.30, (yTop + yBot) / 2 + 4);

// pulling force arrow, dashes crawl with t
ctx.strokeStyle = C.accent;
ctx.setLineDash([6, 4]);
ctx.lineDashOffset = -(t * 30) % 10;
var ay = (yTop + yBot) / 2;
ctx.beginPath(); ctx.moveTo(px0 + slabW + 8, ay); ctx.lineTo(px0 + slabW + 54, ay); ctx.stroke();
ctx.setLineDash([]);
ctx.beginPath();
ctx.moveTo(px0 + slabW + 4, ay); ctx.lineTo(px0 + slabW + 16, ay - 5); ctx.lineTo(px0 + slabW + 16, ay + 5);
ctx.closePath(); ctx.fillStyle = C.accent; ctx.fill();
ctx.fillText("F pulls the slab in", px0 + slabW + 20, ay - 10);

// fringing note + edge marker
ctx.fillStyle = C.ink;
ctx.fillText("x", px0 + slabW / 2 - 3, yTop - 12);
ctx.strokeStyle = C.rule;
ctx.setLineDash([2, 4]);
ctx.beginPath(); ctx.moveTo(px0 + slabW, yTop - 20); ctx.lineTo(px0 + slabW, yBot + 20); ctx.stroke();
ctx.setLineDash([]);

// battery symbol
ctx.strokeStyle = C.figure;
var bx = px0 + plateL + 24;
ctx.beginPath(); ctx.moveTo(px0 + plateL, yTop - 4); ctx.lineTo(bx, yTop - 4);
ctx.lineTo(bx, (yTop + yBot) / 2 - 8); ctx.stroke();
ctx.beginPath(); ctx.moveTo(bx - 9, (yTop + yBot) / 2 - 8); ctx.lineTo(bx + 9, (yTop + yBot) / 2 - 8); ctx.stroke();
ctx.beginPath(); ctx.moveTo(bx - 4, (yTop + yBot) / 2); ctx.lineTo(bx + 4, (yTop + yBot) / 2); ctx.stroke();
ctx.beginPath(); ctx.moveTo(bx, (yTop + yBot) / 2); ctx.lineTo(bx, yBot + 4); ctx.lineTo(px0 + plateL, yBot + 4); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText(V.toFixed(0) + " V", bx + 12, (yTop + yBot) / 2 + 4);

// C(x) graph
var gx0 = W * 0.12, gx1 = W * 0.80, gy0 = H * 0.92, gy1 = H * 0.56;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(gx0, gy0); ctx.lineTo(gx1, gy0); ctx.stroke();
ctx.beginPath(); ctx.moveTo(gx0, gy0); ctx.lineTo(gx0, gy1); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("x (cm)", gx1 - 34, gy0 + 16);
ctx.fillText("C", gx0 - 12, gy1 + 2);

var Cmin = eps0 * wm * Lm / dm;
var Cmax = eps0 * wm * kap * Lm / dm;
ctx.strokeStyle = C.figure;
ctx.beginPath();
for (var i = 0; i <= 40; i++) {
  var xx = Lm * i / 40;
  var cc = eps0 * wm * (Lm - xx + kap * xx) / dm;
  var gx = gx0 + (gx1 - gx0) * (i / 40);
  var gy = gy0 - (gy0 - gy1) * (cc - Cmin) / (Cmax - Cmin + 1e-18);
  i === 0 ? ctx.moveTo(gx, gy) : ctx.lineTo(gx, gy);
}
ctx.stroke();
var mx = gx0 + (gx1 - gx0) * frac;
var my2 = gy0 - (gy0 - gy1) * (Cx - Cmin) / (Cmax - Cmin + 1e-18);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(mx, my2, 4, 0, 6.2832); ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("C rises in a straight line with x, so dC/dx is the same everywhere", gx0, gy1 - 8);

out.note = "C = " + (Cx * 1e12).toFixed(1) + " pF,  dC/dx = " +
  (eps0 * wm * (kap - 1) / dm * 1e12 / 100).toFixed(2) + " pF/cm,  F = " + (F * 1000).toFixed(3) + " mN (same at every x)";
